/**
 * Extract the modification time (ms since epoch) from a getFileInfo content string.
 */
function extractMtime(content: string): number {
  try {
    const obj = JSON.parse(content);
    const candidates = [
      obj.modified, obj.mtime, obj.lastModified,
      obj.creationTime, obj.created, obj.last_modified,
      obj.ctime, obj.birthtime
    ];
    for (const ts of candidates) {
      if (ts === null || ts === undefined) continue;
      const ms = typeof ts === "number" ? ts : Date.parse(ts);
      if (!Number.isNaN(ms) && ms > 0) return ms;
    }
  } catch {
    // not JSON
  }

  for (const line of content.split("\n")) {
    if (/modified|mtime|last.?modified/i.test(line)) {
      const ts = parseTimestamp(line);
      if (ts !== 0) return ts;
    }
  }

  return parseTimestamp(content);
}

